  function legacyControlByLabel(label){
    var target=norm(label),list=legacyControls(),exact=null,partial=null;
    list.some(function(el){
      if(el.closest&&el.closest('[data-slv8-visible]'))return false;
      var value=norm(el.textContent||el.value||el.getAttribute('aria-label')||el.title||'');
      if(value===target){exact=el;return true;}
      if(!partial && value && (value.indexOf(target)>=0||target.indexOf(value)>=0))partial=el;
      return false;
    });
    return exact||partial;
  }

  function routeFromPath(){
    var p=location.pathname.replace(/^\/public-demo/,'');
    if(/\/player\/profile\/?$/i.test(p)||p==='/player/profile')return'profile';
    if(/^\/scout\/events\/[^/]+\/?$/i.test(p))return'eventDetail';
    if(/\/scout\/onboarding\/?$/i.test(p))return'onboarding';
    if(/\/scout\/dashboard\/?$/i.test(p))return'dashboard';
    if(/\/scout\/player-search\/?$/i.test(p))return'search';
    if(/\/scout\/rankings\/?$/i.test(p))return'rankings';
    if(/\/scout\/pipeline\/?$/i.test(p))return'pipeline';
    if(/\/scout\/compare-players\/?$/i.test(p))return'compare';
    if(/\/scout\/predictions\/?$/i.test(p))return'predictions';
    if(/\/scout\/fixtures\/?$/i.test(p))return'fixtures';
    if(/\/scout\/events\/?$/i.test(p))return'events';
    if(/\/scout\/usage-requests\/?$/i.test(p))return'usage';
    if(/\/scout\/exports\/?$/i.test(p))return'exports';
    if(/\/scout\/chat\/?$/i.test(p))return'chat';
    if(/\/scout\/notifications\/?$/i.test(p))return'notifications';
    if(/\/scout\/settings\/?$/i.test(p))return'settings';
    if(/\/scout\/preferences\/?$/i.test(p))return'preferences';
    if(/\/scout\/setup\/?$/i.test(p))return'setup';
    if(/\/scout\/report-a-concern\/?$/i.test(p))return'concern';
    return text(document.body&&document.body.dataset&&document.body.dataset.scoutRoute)||'dashboard';
  }
  function sourceWrap(id,html){return'<div id="'+esc(id)+'">'+html+'</div>';}
  function render(view,keepScroll){
    if(!SOURCE[view])view=VIEW_BY_ROUTE[S.route]||'dashboard';
    S.view=view;
    if(!S.content)return;
    var d=SOURCE[view];
    var y=keepScroll?window.scrollY:0;
    S.content.innerHTML=
      '<div class="slv8-desktop-copy" data-slv8-visible="desk">'+sourceWrap(d.deskId,d.desk)+'</div>'+
      '<div class="slv8-mobile-copy" data-slv8-visible="field">'+sourceWrap(d.fieldId,d.field)+'</div>';
    syncIdentity();
    bindVisible();
    hydrate(view).catch(function(e){console.error('[Scout Desk/Field hydrate]',e);});
    if(keepScroll)setTimeout(function(){window.scrollTo(0,y);},0);
  }
