  async function generateExport(root){
    var ps=labelSelect(root,'Player'),fmt=labelSelect(root,'Export format'),pid=ps&&ps.value;
    if(!pid){toast('Choose a player.',true);return;}
    if(isDemo()){
      var p=S.players.find(function(x){return String(x.id)===String(pid);})||{};
      download('ScoutLink-'+playerName(p).replace(/\s+/g,'-')+'-profile.csv','text/csv;charset=utf-8','Field,Value\nName,"'+playerName(p).replace(/"/g,'""')+'"\nPosition,"'+playerPos(p)+'"\nAge group,"'+age(p)+'"\nOverall,'+playerOverall(p)+'\nCompatibility,'+playerCompat(p));
      toast('Demo export created.');render('exports');return;
    }
    var r=await request('POST','/api/exports/player',{playerId:pid,format:/excel|summary/i.test(fmt&&fmt.value)?'EXCEL':'PDF'});
    var data=unwrap(r)||r;
    if(data.downloadUrl||data.url){window.open(data.downloadUrl||data.url,'_blank','noopener');}
    else if(data.content){download(data.fileName||'scoutlink-export.txt',data.mimeType||'text/plain',data.content);}
    toast('Export generated.');S.usage=null;render('exports');
  }
