  function v9BriefRank(player){
    var sorted=S.players.slice().sort(function(a,b){return(playerCompat(b)||playerOverall(b))-(playerCompat(a)||playerOverall(a));});
    var index=sorted.findIndex(function(p){return String(p.id)===String(player&&player.id);});
    return index>=0?index+1:null;
  }
  function v9MetricValue(player,metric){
    var apps=Math.max(0,num(player&&player.appearances));
    if(metric==='Overall vs brief')return playerCompat(player)||playerOverall(player);
    if(metric==='Overall rating')return playerOverall(player);
    if(metric==='Position fit')return num(player&&(
      player.position_fit_score||
      player._analysis&&player._analysis.positionRatings&&player._analysis.positionRatings.bestCurrentScore||
      playerCompat(player)
    ));
    if(metric==='Development potential')return num(player&&(
      player.potential_rating||
      player._analysis&&player._analysis.overallBreakdown&&player._analysis.overallBreakdown.potentialRating||
      playerOverall(player)
    ));
    if(metric==='Goals')return num(player&&player.goals);
    if(metric==='Goals per game')return apps?num(player&&player.goals)/apps:0;
    if(metric==='Assists')return num(player&&player.assists);
    if(metric==='Assists per game')return apps?num(player&&player.assists)/apps:0;
    if(metric==='Clean sheets')return num(player&&player.clean_sheets);
    if(metric==='Clean sheets per game')return apps?num(player&&player.clean_sheets)/apps:0;
    if(metric==='Appearances')return apps;
    if(metric==='Financial value')return num(player&&player.transfer_value);
    return playerOverall(player);
  }
  function v9MetricDisplay(player,metric){
    var value=v9MetricValue(player,metric);
    if(metric==='Financial value')return money(value);
    if(/per game/i.test(metric))return value.toFixed(2);
    if(['Goals','Assists','Clean sheets','Appearances'].indexOf(metric)>=0)return String(Math.round(value));
    return Math.round(value)+' <small>/100</small>';
  }
