  hydratePlayerSelects=function(root){
    var playerLabels=['player a','player b','player','player optional','player or person involved'];
    root.querySelectorAll('select').forEach(function(sel){
      var f=sel.closest('.field'),l=f&&f.querySelector('label');if(!l)return;
      var label=norm(l.textContent),matched=playerLabels.some(function(prefix){return label.indexOf(prefix)===0;});if(!matched)return;
      var isCompare=label.indexOf('player a')===0||label.indexOf('player b')===0;
      var isConcern=label.indexOf('player or person')===0;
      var rows=[];
      if(isCompare||label==='player'||label.indexOf('player optional')===0)rows.push({id:'',first_name:'Select',last_name:'a player…'});
      if(isConcern)rows.push({id:'',first_name:'Not',last_name:'applicable'});
      rows=rows.concat(S.players);
      var current=sel.value;
      setSelectOptions(sel,rows,function(p){return p.id||'';},function(p){return p.id?playerName(p):(isConcern?'Not applicable':'Select a player…');},current);
    });
  };

  hydrateRankings=function(root){
    var metricSel=labelSelect(root,'Rank by');
    if(metricSel)setSelectOptions(metricSel,V9_RANKINGS,function(x){return x;},function(x){return x;},metricSel.value||'Overall vs brief');
    v9SetRequiredLabel(root,'Rank by',false);
    var ageSel=labelSelect(root,'Age group');
    var metric=metricSel?metricSel.value:'Overall vs brief';
    var list=S.players.slice();
    if(ageSel&&ageSel.value&&!/^all/i.test(ageSel.value))list=list.filter(function(p){return age(p)===ageSel.value;});
    list.sort(function(a,b){var diff=v9MetricValue(b,metric)-v9MetricValue(a,metric);return diff||playerOverall(b)-playerOverall(a);});
    var card=Array.prototype.find.call(root.querySelectorAll('.card'),function(c){return c.querySelector('.rank-num');});if(!card)return;
    var sample=card.querySelector('.list-row'),body=card.querySelector('.card-b');if(!sample||!body)return;
    var tpl=sample.cloneNode(true);body.innerHTML='';
    list.slice(0,20).forEach(function(p,i){
      var row=tpl.cloneNode(true);row.dataset.playerId=p.id;
      var rn=row.querySelector('.rank-num');if(rn)rn.textContent=i+1;
      var av=row.querySelector('.avatar');if(av)av.textContent=initials(playerName(p));
      var who=row.querySelector('.who');if(who){var b=who.querySelector('b');if(b)b.textContent=playerName(p);var sp=who.querySelector('span');if(sp)sp.textContent=[playerPos(p),age(p),team(p)].filter(Boolean).join(' · ');}
      var score=row.querySelector('.rate-chip')||row.querySelector('.list-row > div:last-of-type');if(score)score.innerHTML=v9MetricDisplay(p,metric);
      row.onclick=function(){go('/player/profile?id='+encodeURIComponent(p.id));};body.appendChild(row);
    });
    var h=card.querySelector('.card-h h3');if(h)h.textContent='Top '+Math.min(20,list.length)+' · '+metric;
    if(!list.length)body.innerHTML='<div class="empty"><b>No ranked players in this filter</b><p>Choose another age group or ranking measure.</p></div>';
  };

  function v9CompareStatValue(player,label){
    var n=norm(label);
    if(n.indexOf('overall')>=0)return{value:String(Math.round(playerOverall(player))),detail:'/100'};
    if(n.indexOf('compatibility')>=0)return{value:String(Math.round(playerCompat(player)||playerOverall(player))),detail:'vs your brief'};
    if(n.indexOf('brief rank')>=0){var rank=v9BriefRank(player);return{value:rank?'#'+rank:'—',detail:'of '+S.players.length};}
    if(n.indexOf('value')>=0)return{value:money(player.transfer_value),detail:'estimated'};
    return{value:'—',detail:''};
  }
  function v9PersonalisedCompareRecommendation(a,b,result){
    var winnerId=result&&result.winnerId;var winner=String(winnerId)===String(b.id)?b:a;
    if(!winnerId){winner=(playerCompat(b)||playerOverall(b))>(playerCompat(a)||playerOverall(a))?b:a;}
    var loser=String(winner.id)===String(a.id)?b:a,brief=v9BriefParts();
    var winnerCompat=Math.round(playerCompat(winner)||playerOverall(winner));
    var loserCompat=Math.round(playerCompat(loser)||playerOverall(loser));
    var clauses=[];
    if(brief.weaknesses.length)clauses.push('your priority to address '+brief.weaknesses.slice(0,2).join(' and '));
    if(brief.roles.length)clauses.push('the role expectation'+(brief.roles.length>1?'s ':' ')+brief.roles.slice(0,2).join(' and '));
    if(brief.style)clauses.push(brief.style+' playing style');
    if(brief.formation)clauses.push(brief.formation+' formation context');
    var context=clauses.length?clauses.join(', '):'the recruitment brief saved in Scout Setup';
    var delta=winnerCompat-loserCompat;
    return playerName(winner)+' is the stronger recommendation for '+context+'. '+
      'Their compatibility is '+winnerCompat+'/100 compared with '+loserCompat+'/100 for '+playerName(loser)+
      (delta?(' ('+Math.abs(delta)+' points '+(delta>0?'higher':'lower')+'). '):'. ')+
      'This recommendation also considers current overall attributes, position relevance and the evidence attached to each player. '+
      'It is specific to your saved brief rather than a claim that '+playerName(winner)+' is universally the better player.';
  }
