        if(/target position/i.test(l.textContent)){l.textContent='Value context';s.innerHTML='<option value="football_value">Football value index</option><option value="development">Development upside</option>';}
        if(/target role/i.test(l.textContent)){l.textContent='Financial goal';s.innerHTML='<option>Evidence-led value review</option><option>Development upside</option><option>Squad value planning</option>';}
