      if(r.recommendation)details.push(r.recommendation);if(Array.isArray(r.paragraphs))details=details.concat(r.paragraphs);if(r.likelyRange)details.push('Likely range: '+r.likelyRange.minimum+'-'+r.likelyRange.maximum+'/100.');if(r.risk)details.push('Risk: '+r.risk+'.');if(Array.isArray(r.tradeOffs)&&r.tradeOffs.length)details.push('Trade-offs: '+r.tradeOffs.join(' '));
