    var inPipe=S.pipeline.some(function(row){return String(row.player_id)===String(playerId);});if(!inPipe){await loadPipeline(true).catch(function(){});inPipe=S.pipeline.some(function(row){return String(row.player_id)===String(playerId);});}
    if(!inPipe){toast('Add this player to your pipeline before messaging their coach.',true);return;}
    if(isDemo()){go('/scout/chat');return;}
